fn initProbe(context: ?*c.JSContext, _: c.JSValue, argc: c_int,
    argv: [*c]c.JSValue) callconv(.c) c.JSValue
{
    const f = active orelse return c.pi_js_exception();
    if (argc != 1) return callable.failure(f.engine, error.ActualInitProbeArgumentRequired, 0);
    return initProbeBody(f, argv[0]) catch |err|
        callable.failure(em.Engine.fromContext(context.?), err, 0);
}
fn initProbeBody(f: *Fixture, wrapper: c.JSValue) !c.JSValue {
    const state = (try f.registry()).unwrap(wrapper) orelse
        return error.ActualInitProbeWrapperRequired;
    if (state.provider != native.Provider.fsreqpromise)
        return error.ActualInitProbeRequestRequired;
    const req: *requests.Request = @alignCast(@fieldParentPtr("wrap", state));
    f.init_probe_calls += 1;
    const actual = req.native_request orelse return error.ActualInitProbeNativeStorageRequired;
    const info = uv.pi_uv_fs_request_info(actual);
    f.init_probe_prepared = info.kind == uv.PI_UV_FS_READ and info.accepted == 0 and
        info.cleaned == 0 and !req.constructed and !req.entry_initialized and req.binding_data == null;
    f.init_probe_before_queue = f.env().requests.head == null and
        f.env().requests.tail == null and f.env().requests.waiting == 0;
    return c.pi_js_undefined();

test "native FS request owner physical Read constructs native storage before init and dispatches the actual view span" {
    var f: Fixture = undefined; try f.init(.{ .physical_read = true }); defer f.deinit();
    var file: PhysicalFile = undefined; try file.init(&f, "0123456789"); defer file.deinit();
    f.env().field(.init).* = 1;
    try f.evaluate(
        \\globalThis.ownerInitProbe = true;
        \\globalThis.actualReadBuffer = new ArrayBuffer(12);
        \\globalThis.actualReadView = new Uint8Array(actualReadBuffer, 3, 6);
    );
    const promise = f.keep(try f.value(
        "actualNativeRead(actualReadFd, actualReadView, 1, 4, 1, actualUsePromises)"));
    const request = try f.firstRequest();
    const wrapper = f.keep(a.duplicate(f.engine, try request.object()));
    const native_request = try f.retainNativeRequest();
    defer uv.pi_uv_fs_request_release(native_request);
    try std.testing.expectEqual(@as(usize, 1), f.init_probe_calls);
    try std.testing.expect(f.init_probe_prepared and f.init_probe_before_queue);
    try std.testing.expect(request.constructed and request.entry.dispatched and request.entry.counted);
    try std.testing.expectEqual(@as(c_int, 1), f.env().requests.waiting);
    try std.testing.expectEqual(c.JS_PROMISE_PENDING, c.JS_PromiseState(f.engine.context, promise));
    try f.pumpPending();
    try f.expectPromiseInt(promise, 4);
    try f.expect(
        \\Array.from(new Uint8Array(actualReadBuffer)).join(",") === "0,0,0,0,49,50,51,52,0,0,0,0"
    );
    try std.testing.expectEqual(@as(c_int, 0), f.env().requests.waiting);
    try std.testing.expect(f.env().requests.head == null and f.env().requests.tail == null);
    try std.testing.expect((try f.registry()).unwrap(wrapper) == null);
    const info = uv.pi_uv_fs_request_info(native_request);
    try std.testing.expectEqual(@as(c_int, 1), info.accepted);
    try std.testing.expectEqual(@as(c_int, 1), info.cleaned);
    try std.testing.expectEqual(@as(i64, 4), info.result);
}

typedef struct PiUvFsInfo {
    int kind;
    int64_t result; /* actual uv_fs_t::result, never a synthesized Promise value */
    const char *path; /* borrowed until request_cleanup */
    int accepted;
    int cleaned;
} PiUvFsInfo;

/* Info is available after immediate negative admission or actual event
 * acquisition, and before a successful request_reset invalidates that result.
 * Cleanup is idempotent and occurs at FSReqAfterScope::Clear;
 * release also handles an unsubmitted native construction rollback.
 * Cleanup does not close a descriptor returned by OPEN: the selected original
 * FileHandle/descriptor consumer owns that independent native resource.
 */
PiUvFsInfo pi_uv_fs_request_info(const PiUvFsRequest *request);
void pi_uv_fs_request_cleanup(PiUvFsRequest *request);

static void *pi_uv_alloc(void *owner, size_t size) {
    if (size > SIZE_MAX - sizeof(PiUvAllocation)) return NULL;
    size_t charge = sizeof(PiUvAllocation) + size;
    if (!pi_js_native_memory_reserve(owner, charge)) return NULL;
    PiUvAllocation *allocation = malloc(charge);
    if (!allocation) {
        pi_js_native_memory_release(owner, charge);
        return NULL;
    }
    allocation->charge = charge;
    void *result = allocation + 1;
    memset(result, 0, size);
    return result;

struct PiUvFsRequest {
    PiUvService *service;
    _Atomic size_t references;
    uv_fs_t uv;
    uv_buf_t buffer;
    JSPiArrayBufferLease backing;
    PiUvEvent event;
    PiUvFsRequest *previous;
    PiUvFsRequest *next;
    int kind;
    int storage_kind; /* immutable generic/typed native allocation admission */
    int descriptor;
    int flags;
    int mode;
    int64_t position;
    int submitted;
    int entered;
    int accepted;
    _Atomic int completed;
    _Atomic int cleaned;
    _Atomic int event_queued;
};

void pi_uv_fs_request_retain(PiUvFsRequest *request) {
    atomic_fetch_add_explicit(&request->references, 1, memory_order_relaxed);
}
void pi_uv_fs_request_cleanup(PiUvFsRequest *request) {
    assert(!request->submitted || atomic_load_explicit(&request->completed, memory_order_acquire));
    if (atomic_exchange_explicit(&request->cleaned, 1, memory_order_acq_rel))
        return;
    /* Actual uv cleanup is delayed until the original AfterScope cutpoint.
     * The independent backing entitlement is no longer used by native work. */
    if (request->entered) uv_fs_req_cleanup(&request->uv);
    JS_PiReleaseArrayBufferLease(&request->backing);
}
void pi_uv_fs_request_release(PiUvFsRequest *request) {
    if (!request || atomic_fetch_sub_explicit(&request->references, 1,
                                              memory_order_acq_rel) != 1)
        return;
    assert(!request->submitted || atomic_load_explicit(&request->completed, memory_order_acquire));
    pi_uv_fs_request_cleanup(request);
    PiUvService *service = request->service;
    pi_uv_free(service->memory_owner, request);
    pi_uv_service_release(service);
}
static PiUvFsRequest *pi_uv_fs_request_allocate(PiUvService *service,
                                               int kind, uint64_t token) {
    PiUvFsRequest *request = pi_uv_alloc(service->memory_owner, sizeof(*request));
    if (!request) return NULL;
    request->service = service;
    request->kind = kind;
    request->storage_kind = kind;
    atomic_init(&request->references, 1);
    atomic_init(&request->completed, 0);
    atomic_init(&request->cleaned, 0);
    atomic_init(&request->event_queued, 0);
    pi_uv_service_retain(service);
    pi_uv_event_prepare(&request->event, service, NULL, NULL,
        PI_UV_FS_REQUEST, PI_UV_FS_COMPLETION, 0, token);
    request->event.allocation = request;
    return request;

static void pi_uv_fs_completed(uv_fs_t *actual) {
    PiUvFsRequest *request = actual->data;
    PiUvService *service = request->service;
    if (request->previous) request->previous->next = request->next;
    else service->fs_requests = request->next;
    if (request->next) request->next->previous = request->previous;
    request->previous = request->next = NULL;
    request->event.info.status = actual->result < 0 ? (int)actual->result : 0;
    if (request->kind == PI_UV_FS_READ && actual->result >= 0)
        request->event.info.length = (size_t)actual->result;
    atomic_fetch_sub_explicit(&service->pending_requests, 1, memory_order_release);
    /* Publish the queued state before completed: observing completed must
     * never admit Reset in the interval before FIFO publication. Only actual
     * dequeue clears this state for an accepted operation. */
    atomic_store_explicit(&request->event_queued, 1, memory_order_release);
    atomic_store_explicit(&request->completed, 1, memory_order_release);
    pi_uv_fs_request_retain(request); /* actual queued event entitlement */
    pi_uv_event_queue(&request->event);
    /* The owner may already have drained the event. Keep this native callback
     * entitlement until all callback accesses have completed. */
    pi_uv_fs_request_release(request);

PiUvFsInfo pi_uv_fs_request_info(const PiUvFsRequest *request) {
    assert(atomic_load_explicit(&request->completed, memory_order_acquire));
    const int cleaned = atomic_load_explicit(&request->cleaned, memory_order_acquire);
    PiUvFsInfo result = {
        .kind = request->kind, .result = (int64_t)request->uv.result,
        .path = cleaned ? NULL : request->uv.path,
        .accepted = request->accepted, .cleaned = cleaned
    };
    return result;
}
PiUvResult pi_uv_fs_request_create(PiUvService *service, int kind,
                                     uint64_t token, PiUvFsRequest **out) {
    if (!out) return pi_uv_result(UV_EINVAL, 0);
    *out = NULL;
    if (!service || (kind != PI_UV_FS_UNASSIGNED && kind != PI_UV_FS_READ &&
                     kind != PI_UV_FS_OPEN && kind != PI_UV_FS_CLOSE))
        return pi_uv_result(UV_EINVAL, 0);
    PiUvFsRequest *request = pi_uv_fs_request_allocate(service, kind, token);
    if (!request) return pi_uv_result(UV_ENOMEM, 1);
    *out = request;
    return pi_uv_result(0, 0);
}

static int pi_uv_fs_submit(PiUvFsRequest *request, PiUvCommand *command, int kind) {
    /* Generic FSReqCallback storage receives its actual operation only after
     * all native input/state checks, at the same real admission cutpoint. */
    assert(request->storage_kind == PI_UV_FS_UNASSIGNED || request->storage_kind == kind);
    request->kind = kind;
    request->submitted = 1;
    const int status = pi_uv_submit(request->service, command);
    if (status < 0 && !request->entered) {
        request->uv.result = status;
        request->uv.path = NULL;
        atomic_store_explicit(&request->completed, 1, memory_order_release);
    }
    return status;
}
static int pi_uv_fs_unsubmitted(PiUvFsRequest *request, int kind) {
    return request && (request->storage_kind == PI_UV_FS_UNASSIGNED ||
                       request->storage_kind == kind) && !request->submitted &&
        !atomic_load_explicit(&request->cleaned, memory_order_acquire);

fn initialize(self: *Request, s: *Scope, data: *BindingData,
    wrapper: c.JSValue, use_bigint: bool, cancel_native: request_state.Cancel,
    native_request: ?*uv.PiUvFsRequest) !void
{
    self.* = .{
        .wrap = undefined, .entry = undefined,
        .use_bigint = use_bigint, .cancel_native = cancel_native,
        .native_request = native_request,
    };
    const registry = try templates.registry(s.engine, data.template_owner);
    self.wrap.initialize(registry, wrapper,
        .{ .mark = mark, .retire = retire, .destroy = destroy },
        native.Provider.fsreqpromise, -1) catch |err|
    {
        self.attached = c.JS_GetOpaque(wrapper, registry.classId(.fsreqpromise)) != null;
        s.boundary.escaping();
        // AsyncWrap construction calls void AsyncReset. An ordinary init
        // rethrow does not skip the later native ReqWrap/derived members.
        // The caller's HandleScope retains that completion through the
        // subsequent SetReturnValue and actual Dispatch operations.
        if (!self.attached or !self.wrap.init_hook_ran or
            err != error.JavaScriptException or s.boundary.fatal) return err;
    };
    self.attached = true;
    // ReqWrapBase queues the real native object after AsyncWrap's init.
    try self.entry.initialize(&self.wrap, cancel_native);
    self.entry_initialized = true;
    try self.wrap.makeWeak();
    self.entry.reset();
    // Original FSReqBase initializes its native BindingData strong pointer
    // after ReqWrap construction and before the derived alias allocations.
    try data.retainNative();
    self.binding_data = data;
    self.stats_field_array = try Fields.create(s, 18, use_bigint);
    self.statfs_field_array = try Fields.create(s, 7, use_bigint);
    self.constructed = true;
}

pub fn createPhysicalRequest(s: *Scope, known_factory: c.JSValue,
    use_bigint: bool, cancel_native: request_state.Cancel, physical: Physical) !c.JSValue
{
    return createRequestBody(s, known_factory, use_bigint, cancel_native, physical);
}
fn createRequestBody(s: *Scope, known_factory: c.JSValue,
    use_bigint: bool, cancel_native: request_state.Cancel, physical: ?Physical) !c.JSValue
{
    const data = try factoryData(s.engine, known_factory);
    const wrapper = try s.own(try templates.newInstance(s.engine, data.template_owner, .fsreqpromise));
    // INIT hook execution makes this a guest-capable operation. Never tag its
    // whole allocation span as a purely native producer.
    try s.pending();
    const resolver = try s.checked(c.JS_PiNewPendingPromise(s.engine.context));
    // Original Object::Set uses kDontThrow; a normal false result continues.
    try s.pending();
    const status = c.JS_SetPropertyValue(s.engine.context, wrapper,
        a.duplicate(s.engine, data.promise_string), a.duplicate(s.engine, resolver), 0);
    try s.pending();
    if (status < 0) return error.MissingActualFSReqPromiseSetReason;

    const self = try data.environment.allocator().create(Request);
    var native_request: ?*uv.PiUvFsRequest = null;
    if (physical) |input| {
        // Only native charged storage is created here. The actual init hook
        // remains in initialize(), outside this proven allocation producer.
        const result = uv.pi_uv_fs_request_create(input.service, input.kind, 0, &native_request);
        if (result.allocation_failed != 0 or result.status < 0) {
            const failure: anyerror = if (result.allocation_failed != 0)
                error.OutOfMemory else error.ActualFSReqPhysicalInputsRequired;
            var completion = a.owned.Completion.initVoid(s.engine, failure);
            data.environment.allocator().destroy(self);
            try completion.finishVoid();
            unreachable;
        }
        if (native_request == null) {
            var completion = a.owned.Completion.initVoid(s.engine, error.ActualFSReqNativeStorageRequired);
            data.environment.allocator().destroy(self);
            try completion.finishVoid();
            unreachable;
        }
    }
    self.initialize(s, data, wrapper, use_bigint, cancel_native, native_request) catch |err| {
        // Record the real construction failure before its partially attached
        // native owner or any derived alias is retired.
        var completion = a.owned.Completion.initVoid(s.engine, err);
        completion.release(c.pi_js_undefined());
        if (self.attached) {
            self.wrap.retire(false) catch {};
        } else {
            if (native_request) |actual| uv.pi_uv_fs_request_release(actual);
            data.environment.allocator().destroy(self);
        }
        try completion.finishVoid();
        unreachable;
    };
    return a.duplicate(s.engine, wrapper);

/// Creation uses the caller's real HandleScope and native constructor
/// allocation cutpoint. No extra Promise or native request is made at
/// Dispatch. The caller preserves this Local through SetReturnValue.
pub fn createReadRequest(self: *Controller, s: *Scope, factory: c.JSValue) !*requests.Request {
    try self.enter(s.engine);
    defer self.leave();
    const wrapper = try s.own(try requests.createPhysicalRequest(s, factory,
        false, cancelRequest, .{ .service = self.service, .kind = uv.PI_UV_FS_READ }));
    const request = try requests.unwrap(s.engine, factory, wrapper);
    if (request.environment() != self.environment)
        return error.ActualFSRequestEnvironmentMismatch;
    return request;
}

/// Private inputs were checked by the genuine native Read binding. The
/// stored request is the one constructed above, not a worker Task copy.
/// An immediate negative Dispatch calls the original AfterInteger directly
/// and never enters Wrapper or the waiting counter.
pub fn dispatchRead(self: *Controller, s: *Scope, request: *requests.Request,
    descriptor: c_int, backing: *const c.JSPiArrayBufferLease,
    offset: usize, length: u32, position: i64) !void
{
    try self.enter(s.engine);
    defer self.leave();
    if (request.environment() != self.environment or
        request.entry.cancel_native != cancelRequest or request.entry.dispatched or
        backing.owner == null or length > std.math.maxInt(i32) or
        offset > backing.byte_length or length > backing.byte_length - offset)
        return error.ActualFSReadDispatchInputsRequired;
    const actual = request.native_request orelse return error.ActualFSNativeRequestRequired;
    request.entry.dispatchStarted();
    try request.entry.setCallback(.{ .request = actual, .call = afterIntegerCallback });
    const status = uv.pi_uv_fs_read(actual, descriptor, @ptrCast(backing),
        offset, length, position);
    if (status >= 0) {
        try request.entry.dispatchAccepted();
        return;
    }
    // AfterInteger may delete the native request. Do not read it afterward.
    try afterInteger(request, actual);
}

fn afterInteger(request: *requests.Request, actual: *uv.PiUvFsRequest) !void {
    const info = uv.pi_uv_fs_request_info(actual);
    if (info.kind != uv.PI_UV_FS_READ) return error.ActualFSReadCompletionRequired;
    var after: after_scope.AfterScope = undefined;
    try after.init(request, .{ .raw = actual, .run = cleanupRequest });
    return after.finish(afterIntegerBody(&after, request, info));
}
fn afterIntegerBody(after: *after_scope.AfterScope, request: *requests.Request,
    info: uv.PiUvFsInfo) !void
{
    // Read's validated Int32 length bounds every successful uv result.
    const result = std.math.cast(c_int, info.result) orelse
        return error.ActualFSReadResultRequired;
    const path: ?[]const u8 = if (info.path == null) null else
        std.mem.span(@as([*:0]const u8, @ptrCast(info.path)));
    if (try after.proceed(.{ .code = result, .syscall = "read", .path = path }))
        try request.resolve(c.JS_NewInt32(after.handles.engine.context, result));

var lease: c.JSPiArrayBufferLease = std.mem.zeroes(c.JSPiArrayBufferLease);
defer c.JS_PiReleaseArrayBufferLease(&lease);
// All preceding operations are intrinsic primitive checks. Acquire the
// original span before init/SetReturnValue can detach or transfer it.
try storage(s, args[1], &lease);
const request = controller.createReadRequest(s, roots[1]) catch |err| {
    s.boundary.escaping();
    // Original empty NewInstance/Resolver/Set Maybe leaves GetReqWrap
    // null, which reaches Read's native CHECK. An attached ordinary init
    // rethrow already completed its native constructor in createRequest.
    // Actual fatal/host/dependency failures retain their existing policy.
    if (err == error.JavaScriptException and !s.boundary.fatal)
        return controller.environment.operations.native_check_failure(
            controller.environment, .fs_read_request);
    return err;
};
var returned = c.pi_js_undefined();
if (request.returnPromise()) |value| {
    returned = try s.own(value);
} else |err| {
    s.boundary.escaping();
    // SetReturnValue is void. Its ordinary failed Get does not remove the
    // non-null request or skip the following native AsyncCall/Dispatch.
    if (err != error.JavaScriptException or s.boundary.fatal) return err;
}
